-- Independent AlgoGym practice expansion from LeetCode public catalog metadata.
-- These are editorial tracks, not verified employer interview-frequency data.
-- Premium-only problems, problem statements, and Hynts' compilation are excluded.
on conflict(id) do nothing;

-- Keep existing positions and user progress; append up to 40 new problems per
-- company from a rotated public catalog to provide deeper, varied practice.
with candidates as (
  select id, row_number() over(order by id)::integer - 1 as n
  from public.interview_questions
  where id in ('lc-two-sum','lc-add-two-numbers','lc-longest-substring-without-repeating-characters','lc-median-of-two-sorted-arrays','lc-longest-palindromic-substring','lc-zigzag-conversion','lc-reverse-integer','lc-string-to-integer-atoi','lc-palindrome-number','lc-regular-expression-matching','lc-container-with-most-water','lc-integer-to-roman','lc-roman-to-integer','lc-longest-common-prefix','lc-3sum','lc-3sum-closest','lc-letter-combinations-of-a-phone-number','lc-4sum','lc-remove-nth-node-from-end-of-list','lc-valid-parentheses','lc-merge-two-sorted-lists','lc-generate-parentheses','lc-merge-k-sorted-lists','lc-swap-nodes-in-pairs','lc-reverse-nodes-in-k-group','lc-remove-duplicates-from-sorted-array','lc-remove-element','lc-find-the-index-of-the-first-occurrence-in-a-string','lc-divide-two-integers','lc-substring-with-concatenation-of-all-words','lc-next-permutation','lc-longest-valid-parentheses','lc-search-in-rotated-sorted-array','lc-find-first-and-last-position-of-element-in-sorted-array','lc-search-insert-position','lc-valid-sudoku','lc-sudoku-solver','lc-count-and-say','lc-combination-sum','lc-combination-sum-ii','lc-first-missing-positive','lc-trapping-rain-water','lc-multiply-strings','lc-wildcard-matching','lc-jump-game-ii','lc-permutations','lc-permutations-ii','lc-rotate-image','lc-group-anagrams','lc-powx-n','lc-n-queens','lc-n-queens-ii','lc-maximum-subarray','lc-spiral-matrix','lc-jump-game','lc-merge-intervals','lc-insert-interval','lc-length-of-last-word','lc-spiral-matrix-ii','lc-permutation-sequence','lc-rotate-list','lc-unique-paths','lc-unique-paths-ii','lc-minimum-path-sum','lc-valid-number','lc-plus-one','lc-add-binary','lc-text-justification','lc-sqrtx','lc-climbing-stairs','lc-simplify-path','lc-edit-distance','lc-set-matrix-zeroes','lc-search-a-2d-matrix','lc-sort-colors','lc-minimum-window-substring','lc-combinations','lc-subsets','lc-word-search','lc-remove-duplicates-from-sorted-array-ii','lc-search-in-rotated-sorted-array-ii','lc-remove-duplicates-from-sorted-list-ii','lc-remove-duplicates-from-sorted-list','lc-largest-rectangle-in-histogram','lc-maximal-rectangle','lc-partition-list','lc-scramble-string','lc-merge-sorted-array','lc-gray-code','lc-subsets-ii','lc-decode-ways','lc-reverse-linked-list-ii','lc-restore-ip-addresses','lc-binary-tree-inorder-traversal','lc-unique-binary-search-trees-ii','lc-unique-binary-search-trees','lc-interleaving-string','lc-validate-binary-search-tree','lc-recover-binary-search-tree','lc-same-tree','lc-symmetric-tree','lc-binary-tree-level-order-traversal','lc-binary-tree-zigzag-level-order-traversal','lc-maximum-depth-of-binary-tree','lc-construct-binary-tree-from-preorder-and-inorder-traversal','lc-construct-binary-tree-from-inorder-and-postorder-traversal','lc-binary-tree-level-order-traversal-ii','lc-convert-sorted-array-to-binary-search-tree','lc-convert-sorted-list-to-binary-search-tree','lc-balanced-binary-tree','lc-minimum-depth-of-binary-tree','lc-path-sum','lc-path-sum-ii','lc-flatten-binary-tree-to-linked-list','lc-distinct-subsequences','lc-populating-next-right-pointers-in-each-node','lc-populating-next-right-pointers-in-each-node-ii','lc-pascals-triangle','lc-pascals-triangle-ii','lc-triangle','lc-best-time-to-buy-and-sell-stock','lc-best-time-to-buy-and-sell-stock-ii','lc-best-time-to-buy-and-sell-stock-iii','lc-binary-tree-maximum-path-sum','lc-valid-palindrome','lc-word-ladder-ii','lc-word-ladder','lc-longest-consecutive-sequence','lc-sum-root-to-leaf-numbers','lc-surrounded-regions','lc-palindrome-partitioning','lc-palindrome-partitioning-ii','lc-clone-graph','lc-gas-station','lc-candy','lc-single-number','lc-single-number-ii','lc-copy-list-with-random-pointer','lc-word-break','lc-word-break-ii','lc-linked-list-cycle','lc-linked-list-cycle-ii','lc-reorder-list','lc-binary-tree-preorder-traversal','lc-binary-tree-postorder-traversal','lc-lru-cache','lc-insertion-sort-list','lc-sort-list','lc-max-points-on-a-line','lc-evaluate-reverse-polish-